def snapshot(filename, start, end, title):
    lines = Path(__file__).with_name('Functions.py').read_text(encoding='utf-8').splitlines()
    font = ImageFont.truetype('C:/Windows/Fonts/consola.ttf', 23)
    heading = ImageFont.truetype('C:/Windows/Fonts/segoeui.ttf', 25)
    excerpt = lines[start-1:end]
    width = max(1250, int(max(font.getlength(line) for line in excerpt))+145)
    img = Image.new('RGB', (width, 135+len(excerpt)*38), '#101c2b')
    draw = ImageDraw.Draw(img)
    draw.text((35, 24), title, font=heading, fill='#f1f5f9')
    draw.text((35, 65), f'Functions.py  /  lines {start}–{end}  /  selected excerpt', font=font, fill='#8fa9c0')
    for row, line in enumerate(excerpt):
        y=120+row*38
        draw.text((28,y), str(start+row), font=font, fill='#65819a')
        draw.text((105,y), line, font=font, fill='#8dd9d4' if line.lstrip().startswith('#') else '#dfebf5')
    img.save(OUT/filename)

snapshot('code-timing.png',93,98,'Sampling interval and timestamp validation')
snapshot('code-filter.png',108,112,'Band-pass design and transient exclusion')

